class Solution {
public List<List<String>> findLadders(String beginWord,String endWord,List<String> wordList){Set<String>left=new HashSet<>(wordList),level=new HashSet<>(Arrays.asList(beginWord));List<List<String>>out=new ArrayList<>();if(!left.contains(endWord))return out;left.remove(beginWord);Map<String,List<String>>parents=new HashMap<>();while(!level.isEmpty()&&!level.contains(endWord)){Set<String>next=new HashSet<>();for(String w:level){char[]a=w.toCharArray();for(int i=0;i<a.length;i++){char old=a[i];for(char c='a';c<='z';c++){a[i]=c;String t=new String(a);if(left.contains(t)){parents.computeIfAbsent(t,x->new ArrayList<>()).add(w);next.add(t);}}a[i]=old;}}left.removeAll(next);level=next;}if(level.contains(endWord))build(endWord,beginWord,parents,new ArrayList<>(),out);return out;}private void build(String w,String begin,Map<String,List<String>>parents,List<String>path,List<List<String>>out){path.add(w);if(w.equals(begin)){List<String>row=new ArrayList<>(path);Collections.reverse(row);out.add(row);}else for(String p:parents.getOrDefault(w,Collections.emptyList()))build(p,begin,parents,path,out);path.remove(path.size()-1);}
}
